if (root == nullptr) {
    return false;
}

Node* current = root;
while (!current->is_leaf) {
    int i = 0;
    // Binary search for the appropriate child pointer
    int low = 0, high = current->num_keys - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (key < current->keys[mid]) {
            high = mid - 1;
        } else if (key > current->keys[mid]) {
            low = mid + 1;
        } else {
            // Key found in internal node, move to right child
            i = mid + 1;
            break;
        }
    }
    if (low > high) {
        i = low;
    }
    current = current->children[i];
}

int low = 0, high = current->num_keys - 1;
while (low <= high) {
    int mid = low + (high - low) / 2;
    if (key == current->keys[mid]) {
        return true;
    } else if (key < current->keys[mid]) {
        high = mid - 1;
    } else {
        low = mid + 1;
    }
}
return false;
// END_CODE

